n=17;c=8
rows=[]
for r in range(n):
 row=[0]*n
 if r<=c:
  row[c-r]=2; row[c+r]=2
 if r>=3:
  if r%2:
   offs=list(range(-(r-2), r-2, 4)) # check r3 -> -1 to <1 => -1
  else:
   offs=list(range(-(r-4), r-3, 4)) # r4 =>0, r6=> -2,2
  for d in offs:
   j=c+d
   if 0<=j<n and row[j]==0: row[j]=1
 rows.append(row)
rows
